--
-- Name: realtime_purge(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.realtime_purge(p_before timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  v_max bigint;
  v_count bigint;
begin
  with d as (delete from realtime_events where at < p_before returning id)
  select max(id), count(*) into v_max, v_count from d;
  if v_max is not null then
    insert into realtime_state (id, purged_through) values (true, v_max)
    on conflict (id) do update set purged_through = greatest(realtime_state.purged_through, excluded.purged_through);
  end if;
  return v_count;
end
$$;

--
-- Name: services_default_category(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.services_default_category() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.category is null then
    new.category := catalog_default_category(new.kind, new.tags);
    insert into catalog_categories (location_id, key, label, colour, sort)
    select new.location_id, c.key, c.label, c.colour, c.sort
    from (values
      ('wash', 'Wash', '#1FB6FF', 10),
      ('addons', 'Add-ons', '#7FD6FF', 20),
      ('tint', 'Tint', '#2EE59D', 30),
      ('detail', 'Detail', '#FFB547', 40)
    ) as c(key, label, colour, sort)
    where c.key = new.category
    on conflict do nothing;
  end if;
  return new;
end
$$;

