);

--
-- Name: sms_usage_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.sms_usage ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.sms_usage_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

